                </Tooltip>
              ) : (
                <span data-slot="tree-label" className="flex-1 text-xs text-muted-foreground font-semibold uppercase tracking-wide truncate select-text" style={treeItemLabelStyle}>
                  {displayLabel}
                </span>
              )}
            </div>
